/bin/bash -lc "node --input-type=module <<'JS'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
const directory = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], { detached: true, env: { ...process.env, PORT: '18080', DB_PATH: join(directory, 'launch.sqlite') }, stdio: ['ignore', 'pipe', 'pipe'] });
try {
  await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => reject(new Error('Startup timeout')), 5000);
    child.stdout.on('data', data => {
      if (String(data).includes('Workboard listening')) { clearTimeout(timeout); resolve(); }
    });
    child.once('error', reject);
  });
  const response = await fetch('http://127.0.0.1:18080/health');
  if (response.status "'!== 200 || JSON.stringify(await response.json()) !== '"'{\"status\":\"ok\"}') throw new Error('Health failed');
  const html = await (await fetch('http://127.0.0.1:18080/')).text();
  if ("'!html.includes('"'<h1>Workboard</h1>')) throw new Error('Homepage failed');
  console.log('npm start, configured PORT/DB_PATH, health, and homepage passed');
} finally {
  process.kill(-child.pid, 'SIGTERM');
  await new Promise(resolve => child.once('exit', resolve));
  await rm(directory, { recursive: true, force: true });
}
JS"

